  p=footer.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run('Manuscript — ')
  page=OxmlElement('w:fldSimple');page.set(qn('w:instr'),'PAGE');p._p.append(page)
